import { useLanguage } from "@/contexts/LanguageContext";
import { handleEmailClick } from "@/utils/email";
import { LucideIcon } from "lucide-react";
import { Link } from "react-router-dom";
import "./ServicePage.css";

interface Feature {
  icon: LucideIcon;
  key: string;
}

interface TechItem {
  key: string;
}

interface ServicePageProps {
  serviceKey: "complianceGuard" | "privacyHub" | "regTechIntelligence" | "safeAgent" | "privateDoc";
  imageSrc: string;
  imageAlt: string;
  features: Feature[];
  techItems: TechItem[];
  hasComplianceSection?: boolean;
}

export function ServicePage({
  serviceKey,
  imageSrc,
  imageAlt,
  features,
  techItems,
  hasComplianceSection = false,
}: ServicePageProps) {
  const { t } = useLanguage();
  const service = t.services[serviceKey];

  // Map service keys to CSS class names
  const classMap: Record<ServicePageProps["serviceKey"], string> = {
    complianceGuard: "compliance-guard-page",
    privacyHub: "privacy-hub-page",
    regTechIntelligence: "regtech-intelligence-page",
    safeAgent: "safe-agent-page",
    privateDoc: "private-doc-page",
  };
  const pageClass = classMap[serviceKey];

  const handleTryClick = () => {
    handleEmailClick(service.title, service.hero.tryButton);
  };

  return (
    <div className={`page service-page ${pageClass}`}>
      <div className="service-hero">
        <div className="service-breadcrumb">
          <Link to="/">{t.common.home}</Link>
          <span className="breadcrumb-separator">/</span>
          <span>{service.title}</span>
        </div>
        <div className="service-hero-content">
          <div className="service-hero-image-container">
            <img src={imageSrc} alt={imageAlt} className="service-hero-image" />
          </div>
          <div className="service-hero-text">
            <h1 className="service-hero-title">{service.hero.title}</h1>
            <h2 className="service-hero-subtitle">{service.hero.subtitle}</h2>
            <p className="service-hero-description">{service.hero.description}</p>
            <div className="service-hero-actions">
              <button className="btn-primary" onClick={handleTryClick}>
                {service.hero.tryButton}
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="service-content">
        <section className="service-features">
          <h3 className="section-title">{service.features.title}</h3>
          <div className="features-grid">
            {features.map((feature) => {
              const Icon = feature.icon;
              const featuresObj = service.features as Record<string, unknown>;
              const featureData = featuresObj[feature.key] as { title: string; description: string } | undefined;

              if (!featureData) return null;

              return (
                <div key={feature.key} className="feature-item">
                  <div className="feature-icon">
                    <Icon size={32} />
                  </div>
                  <h4>{featureData.title}</h4>
                  <p>{featureData.description}</p>
                </div>
              );
            })}
          </div>
        </section>

        <section className="service-technology">
          <h3 className="section-title">{service.technology.title}</h3>
          <div className="tech-grid">
            {techItems.map((tech) => {
              const techObj = service.technology as Record<string, unknown>;
              const techData = techObj[tech.key] as { title: string; description: string } | undefined;

              if (!techData) return null;

              return (
                <div key={tech.key} className="tech-item">
                  <h4>{techData.title}</h4>
                  <p>{techData.description}</p>
                </div>
              );
            })}
          </div>
        </section>

        {hasComplianceSection && "compliance" in service && service.compliance && (
          <section className="service-compliance">
            <h3 className="section-title">{service.compliance.title}</h3>
            <p className="section-description">{service.compliance.description}</p>
          </section>
        )}
      </div>
    </div>
  );
}
