import { BrowserRouter, Route, Routes } from "react-router-dom";
import { Layout } from "./components/Layout/Layout";
import { ScrollToTop } from "./components/ScrollToTop";
import { About } from "./pages/About";
import { ComplianceGuard } from "./pages/ComplianceGuard";
import { Dashboard } from "./pages/Dashboard";
import { Home } from "./pages/Home";
import { NotFound } from "./pages/NotFound";
import { PrivacyHub } from "./pages/PrivacyHub";
import { PrivateDoc } from "./pages/PrivateDoc";
import { RegTechIntelligence } from "./pages/RegTechIntelligence";
import { SafeAgent } from "./pages/SafeAgent";

// Get base path from vite config (matches import.meta.env.BASE_URL)
const basename = import.meta.env.BASE_URL.replace(/\/$/, "");

function App() {
  return (
    <BrowserRouter basename={basename}>
      <ScrollToTop />
      <Routes>
        <Route path="/" element={<Layout />}>
          <Route index element={<Home />} />
          <Route path="dashboard" element={<Dashboard />} />
          <Route path="about" element={<About />} />
          <Route path="services/compliance-guard" element={<ComplianceGuard />} />
          <Route path="services/privacy-hub" element={<PrivacyHub />} />
          <Route path="services/regtech-intelligence" element={<RegTechIntelligence />} />
          <Route path="services/safe-agent" element={<SafeAgent />} />
          <Route path="services/private-doc" element={<PrivateDoc />} />
          <Route path="*" element={<NotFound />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}

export default App;
